-- Every table has hidden system columns. Ask for them explicitly.
SELECT ctid, xmin, xmax, * FROM accounts WHERE id = 1;
--  ctid  | xmin | xmax | id | balance
-- (0,1)  |  742 |    0 |  1 |    100

BEGIN;
UPDATE accounts SET balance = 150 WHERE id = 1;

-- Same logical row, new ctid: a second physical version now exists.
SELECT ctid, xmin, xmax, * FROM accounts WHERE id = 1;
--  ctid  | xmin | xmax | id | balance
-- (0,2)  |  743 |    0 |  1 |    150
COMMIT;

-- Both versions are still on the page. Prove it:
CREATE EXTENSION IF NOT EXISTS pageinspect;
SELECT lp, lp_off, t_xmin, t_xmax, t_ctid
FROM   heap_page_items(get_raw_page('accounts', 0));
--  lp | lp_off | t_xmin | t_xmax | t_ctid
--   1 |   8152 |    742 |    743 | (0,2)     <- superseded, points at its successor
--   2 |   8112 |    743 |      0 | (0,2)     <- current

-- How much of the table is dead weight right now:
SELECT relname, n_live_tup, n_dead_tup, last_autovacuum
FROM   pg_stat_user_tables
ORDER  BY n_dead_tup DESC
LIMIT  10;

blocks.mermaid:
flowchart TD
  START["Need a free buffer"] --> HAND["Look at buffer under the clock hand"]
  HAND --> PIN{"Pinned?"}
  PIN -->|"yes - someone is using it"| NEXT["Advance the hand"]
  PIN -->|"no"| USE{"usage_count greater than 0?"}
  USE -->|"yes"| DEC["Decrement usage_count"] --> NEXT
  USE -->|"no"| DIRTY{"Dirty?"}
  DIRTY -->|"yes"| FLUSH["Flush WAL, then write the page"] --> EVICT
  DIRTY -->|"no"| EVICT["Evict and reuse the frame"]
  NEXT --> HAND
